import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// n lines of `price` x 1
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

// Issue #12: the customer discount is applied exactly once.
test('customer discount is applied once (fewer than 10 lines)', () => {
  // 1,000 less 10% = 900
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('10 or more lines: customer discount, then the 5% bulk discount once', () => {
  // 10,000 less 10% = 9,000; less 5% = 8,550
  assert.equal(total(lines(10, 1000), 0.1), 8550);
  // more than 10 lines: 11,000 less 10% = 9,900; less 5% = 9,405
  assert.equal(total(lines(11, 1000), 0.1), 9405);
});

test('9 lines: customer discount only, no bulk discount', () => {
  // 9,000 less 10% = 8,100
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

// Issue #12: totals with a discount rate of 0 must stay as they were.
test('discount rate 0: totals are unchanged', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0), 1000);
  // bulk discount only: 10,000 less 5% = 9,500
  assert.equal(total(lines(10, 1000), 0), 9500);
  assert.equal(total(lines(9, 1000), 0), 9000);
  // rounded once at the end: 3,330 less 5% = 3,163.5 -> 3,164
  assert.equal(total(lines(10, 333), 0), 3164);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
